<form method="POST" action="{{ route('admin.offerings.store') }}">@csrf<div class="card"><div class="card-header"><h3 class="card-title">Offering Capture</h3></div><div class="card-body"><div class="row g-3 mb-4"><div class="col-md-4"><label class="form-label">Service</label><select class="form-select" name="service_id" required>@foreach($services as $service)<option value="{{ $service->id }}">{{ $service->name }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Branch</label><select class="form-select" name="branch_id" required>@foreach($branches as $branch)<option value="{{ $branch->id }}">{{ $branch->name }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Date</label><input class="form-control" type="date" name="date" value="{{ today()->toDateString() }}" required></div></div><div class="table-responsive"><table class="table" id="items"><thead><tr><th>Giving type</th><th>Fund</th><th>Method</th><th>Account</th><th>Giver name</th><th>Amount</th><th></th></tr></thead><tbody><tr class="item-row"><td><select class="form-select" data-field="giving_type_id">@foreach($givingTypes as $item)<option value="{{ $item->id }}" data-default-fund="{{ $item->default_fund_id }}">{{ $item->name }}</option>@endforeach</select></td><td><select class="form-select" data-field="fund_id">@foreach($funds as $item)<option value="{{ $item->id }}">{{ $item->name }}</option>@endforeach</select></td><td><select class="form-select" data-field="payment_method_id">@foreach($paymentMethods as $item)<option value="{{ $item->id }}">{{ $item->name }}</option>@endforeach</select></td><td><select class="form-select" data-field="financial_account_id">@foreach($accounts as $item)<option value="{{ $item->id }}">{{ $item->name }}</option>@endforeach</select></td><td><input class="form-control" data-field="giver_name"></td><td><input class="form-control amount" data-field="amount" type="number" min="0.0001" step="0.0001" required><input type="hidden" data-field="currency" value="{{ $currency }}"></td><td><button class="btn btn-sm btn-outline-danger remove" type="button">×</button></td></tr></tbody></table></div><button id="add-row" class="btn btn-outline-secondary" type="button">Add row</button><div class="text-end fs-3 mt-3">Total: <strong id="offering-total">0.00</strong></div></div><div class="card-footer d-flex justify-content-end gap-2"><button class="btn btn-outline-primary" name="status" value="draft">Save draft</button><button class="btn btn-primary" name="status" value="counted">Mark counted</button></div></div></form>
@push('after_scripts')<script>(()=>{const body=document.querySelector('#items tbody');const rename=()=>[...body.children].forEach((r,i)=>r.querySelectorAll('[data-field]').forEach(x=>x.name=`items[${i}][${x.dataset.field}]`));const total=()=>document.getElementById('offering-total').textContent=[...document.querySelectorAll('.amount')].reduce((s,i)=>s+(Number(i.value)||0),0).toFixed(2);const selectDefaultFund=row=>{const givingType=row.querySelector('[data-field="giving_type_id"]');const fund=row.querySelector('[data-field="fund_id"]');const defaultFund=givingType?.selectedOptions[0]?.dataset.defaultFund;if(defaultFund&&fund?.querySelector(`option[value="${CSS.escape(defaultFund)}"]`)){fund.value=defaultFund;fund.dispatchEvent(new Event('change',{bubbles:true}))}};document.getElementById('add-row').onclick=()=>{body.append(body.firstElementChild.cloneNode(true));body.lastElementChild.querySelectorAll('input').forEach(i=>{if(i.type!=='hidden')i.value=''});selectDefaultFund(body.lastElementChild);rename()};body.addEventListener('click',e=>{if(e.target.classList.contains('remove')&&body.children.length>1){e.target.closest('tr').remove();rename();total()}});body.addEventListener('change',e=>{if(e.target.dataset.field==='giving_type_id')selectDefaultFund(e.target.closest('tr'))});body.addEventListener('input',total);selectDefaultFund(body.firstElementChild);rename()})();</script>@endpush
